import Foundation
import IlliquidCore

/// Main-actor admission orders automation requests independently of filesystem
/// completion order. Waiting requests allocate no worker and never bypass the
/// playback core. Cancelling a waiter cannot release its successor early.
@MainActor
final class PlaybackAutomationQueue {
    private var tail: Task<Void, Never>?
    private var pending = 0

    func perform<Value: Sendable>(_ operation: @escaping @MainActor @Sendable () async throws -> Value) async throws -> Value {
        guard pending < PlaybackAutomationPolicy.maximumPendingRequests else { throw PlaybackAutomationError.busy }
        try Task.checkCancellation()
        pending += 1
        let predecessor = tail
        let job = Task { @MainActor in
            await predecessor?.value
            try Task.checkCancellation()
            return try await operation()
        }
        let completion = Task { @MainActor in _ = try? await job.value }
        tail = completion
        defer {
            pending -= 1
            if pending == 0 { tail = nil }
        }
        return try await withTaskCancellationHandler {
            try await job.value
        } onCancel: { job.cancel() }
    }
}

var hasPendingTrackSelection: Bool {
    guard let tracks = model.core.state.activeSession?.tracks else { return false }
    return tracks.phase != .idle
}

var acknowledgedExternalSubtitleURL: URL? {
    guard !hasPendingTrackSelection,
          case let .external(source) = model.core.state.activeSession?.tracks.effectiveSubtitle,
          source.rawValue.hasPrefix("subtitle:/") else { return nil }
    return URL(fileURLWithPath: String(source.rawValue.dropFirst("subtitle:".count)))
}

@discardableResult
func selectAutomaticSubtitle() -> Bool { send(.selectSubtitle(.automatic)) }

if let model {
    PlayerCommands(model: model)
    CommandMenu("Media Tools") {
        Button("Caption Navigation…") { showsCaptions = true }
            .keyboardShortcut("f", modifiers: [.command, .shift])
            .disabled(model.player.viewStore.currentSource == nil)
        Button("Preferences for This File…") { showsMediaPreferences = true }
            .disabled(!model.player.canEditCurrentMediaSettings)
    }
}

/// Immutable bytes used by the active text subtitle pipeline. A separate
/// caption index cannot accidentally read a newer on-disk sidecar while
/// playback is still displaying the previously loaded version.
/// Physical replacement completion, used only to avoid returning a product
/// result while a native candidate can still replace its clock/resources.
public var hasPendingMediaReplacement: Bool {
    !replacementTasks.isEmpty || deferredReplacementRequest != nil || pendingCommittedReplacement != nil
}

public var externalCaptionDocument: NativeCaptionDocument? {
    guard !hasPendingMediaReplacement,
          case let .external(url) = subtitleSource,
          let prepared = preparedExternalSubtitle, prepared.url == url,
          let data = prepared.data else { return nil }
    return NativeCaptionDocument(url: url, assData: data)
}

